 const {data:items,error:e}=await supabase.from('orders').select('id,status,amount,checklist,created_at,listing_id,listings(title),buyer:profiles!orders_buyer_id_fkey(display_name),seller:profiles!orders_seller_id_fkey(display_name)').in('status',['payment_approved','completed']).order('approved_at',{ascending:false});if(e)throw e;
 const {data:reports}=await supabase.rpc('admin_list_reports');
