  body+=`<section class="card card-pad stack" style="margin-top:18px"><div class="row between"><div><p class="eyebrow">ADMIN DEAL CHAT</p><h2>${esc(d.listings?.title||'Free Fire ID')}</h2><p class="muted">${esc(d.buyer?.display_name||'Buyer')} ↔ ${esc(d.seller?.display_name||'Seller')} · ${pkr(d.amount)}</p></div><button class="btn small" data-action="admin-close-deal">Close</button></div><div class="chat-box">${(msgs||[]).map(m=>`<div class="bubble ${m.sender_role==='admin'?'mine':''}"><small>${esc(m.sender_role)} · ${date(m.created_at)}</small>${esc(m.body)}</div>`).join('')||'<p class="muted">No messages yet.</p>'}</div><form id="admin-chat-form" data-order="${d.id}" class="row"><input class="control" name="body" required maxlength="2000" placeholder="Admin message…"><button class="btn primary">Send as Admin</button></form><h3>Account Handover Checklist</h3>${[['seller_confirmed','Seller confirmed they are authorized to transfer the game account'],['buyer_received','Buyer confirmed receipt of the game account'],['account_secured','Buyer reviewed account security settings'],['transfer_completed','Account handover completed']].map(([k,label])=>`<label class="checkline"><input type="checkbox" disabled ${d.checklist?.[k]?'checked':''}>${label}</label>`).join('')}<h3>Deal Reports</h3>${rs.map(r=>`<div class="review"><p>${esc(r.reason)}</p><span class="help">${date(r.created_at)} · ${r.resolved?'Resolved':'Open'}</span>${!r.resolved?`<button class="btn small" data-action="report-resolve" data-id="${r.id}" data-resolved="true">Mark resolved</button>`:''}</div>`).join('')||'<p class="muted">No reports for this deal.</p>'}</section>`;
